const out = [];
for (const it of items) {
  const j = it.json;
  const fromAddr = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || (j.from && j.from.text) || (typeof j.from === 'string' ? j.from : '') || '';
  const toAddr = (j.to && j.to.value && j.to.value[0] && j.to.value[0].address) || (j.to && j.to.text) || (typeof j.to === 'string' ? j.to : '') || '';
  const cuerpo = j.text || j.textAsHtml || j.snippet || '';
  const rl = String(fromAddr).toLowerCase();
  const es_auto = /noreply|no-reply|no_responder|mailer-daemon|auto-submitted|notification|postmaster|bounce/.test(rl);
  if (!j.id) continue;
  out.push({ json: {
    mensaje_id: j.id,
    hilo_id: j.threadId || null,
    fecha: j.date || null,
    remitente: fromAddr || null,
    para: toAddr || null,
    asunto: j.subject || null,
    cuerpo: cuerpo ? String(cuerpo).slice(0, 20000) : null,
    etiquetas: Array.isArray(j.labelIds) ? j.labelIds.join(',') : null,
    es_automatico: es_auto,
    store_id: '{{STORE_ID}}',
    extraido_por: 'gmail_live_{{TIENDA_NOMBRE}}'
  }});
}
return out;

// Las firmas de correo traen logos e iconos incrustados. Si los guardaramos todos, el
// SAC veria 40 logotipos y ninguna foto util. Se filtra por tamano y tipo: menos de
// 20 KB es siempre firma o icono; solo interesan imagenes y PDF (boletas).
const MIN_BYTES = 20 * 1024;
const OK = /^(image\/(jpeg|png|webp|gif|heic)|application\/pdf)$/i;
const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  const bin = item.binary || {};
  for (const clave of Object.keys(bin)) {
    const b = bin[clave];
    const tipo = String(b.mimeType || '');
    const tam = Number(b.fileSize || 0) || (b.data ? Math.floor(b.data.length * 0.75) : 0);
    if (!OK.test(tipo)) continue;
    if (tam < MIN_BYTES) continue;
    salida.push({
      json: {
        mensaje_id: j.id,
        hilo_id: j.threadId || null,
        nombre: b.fileName || (clave + '.bin'),
        tipo: tipo,
        tamano: tam,
        ruta: String(j.id) + '/' + (b.fileName || clave),
        es_imagen: /^image\//i.test(tipo),
        clave_binaria: clave
      },
      binary: { data: b }
    });
  }
}
return salida;
